<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand</title>
<style>
  :root { --accent:#6ea8ff; }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    padding: 24px;
    color: #e6e6ea;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    background: radial-gradient(1200px 800px at 50% -10%, #1a1d29 0%, #0b0c11 60%);
  }
  h1 {
    font-size: 17px;
    font-weight: 600;
    letter-spacing: .6px;
    margin: 4px 0 0;
    color: #c9ceda;
  }
  #sand {
    width: 500px;
    height: 500px;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    border-radius: 12px;
    background: #101016;
    box-shadow: 0 20px 60px rgba(0,0,0,.55), inset 0 0 0 1px rgba(255,255,255,.06);
    touch-action: none;
    user-select: none;
    cursor: crosshair;
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: center;
    justify-content: center;
    max-width: 560px;
  }
  .btn {
    appearance: none;
    border: 1px solid rgba(255,255,255,.09);
    background: #1c1e28;
    color: #e6e6ea;
    padding: 10px 15px;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background .15s ease, transform .05s ease, box-shadow .15s ease;
    user-select: none;
  }
  .btn:hover { background: #262938; }
  .btn:active { transform: translateY(1px); }
  .btn.active {
    box-shadow: 0 0 0 2px var(--accent), 0 6px 20px rgba(110,168,255,.35);
    background: #29304a;
  }
  .swatch {
    display: inline-block;
    width: 13px; height: 13px;
    margin-right: 7px;
    border-radius: 4px;
    vertical-align: middle;
    border: 1px solid rgba(0,0,0,.35);
  }
  #clear { background: #2a1c1e; border-color: rgba(255,96,96,.22); }
  #clear:hover { background: #3a2328; }
  .size-ctrl {
    display: flex;
    align-items: center;
    gap: 9px;
    font-size: 13px;
    color: #9aa0b0;
    background: #171922;
    border: 1px solid rgba(255,255,255,.07);
    padding: 8px 12px;
    border-radius: 10px;
  }
  input[type=range] { accent-color: var(--accent); width: 110px; }
  .hint { font-size: 12px; color: #6f7585; margin: -6px 0 0; }
</style>
</head>
<body>
  <h1>FALLING&nbsp;SAND</h1>
  <canvas id="sand"></canvas>
  <p class="hint">Click &amp; drag to paint · choose a material below</p>
  <div class="controls">
    <button class="btn active" id="mat-sand" data-mat="sand"><span class="swatch" style="background:#e0c886"></span>Sand</button>
    <button class="btn" id="mat-water" data-mat="water"><span class="swatch" style="background:#3878d6"></span>Water</button>
    <button class="btn" id="mat-wall" data-mat="wall"><span class="swatch" style="background:#808492"></span>Wall</button>
    <button class="btn" id="mat-acid" data-mat="acid"><span class="swatch" style="background:#86e65a"></span>Acid</button>
    <button class="btn" id="mat-empty" data-mat="empty"><span class="swatch" style="background:#101016;border:1px solid rgba(255,255,255,.2)"></span>Erase</button>
    <div class="size-ctrl">Brush <input type="range" id="brush" min="1" max="12" value="3"><span id="brushv">3</span></div>
    <button class="btn" id="clear">Clear</button>
  </div>

<script>
(function () {
  "use strict";

  // ---- Grid dimensions (cells). Both >= 80. Canvas is rendered at 1px/cell
  //      and scaled up via CSS so it easily clears 400x400 CSS px. ----
  var W = 100, H = 100;

  // Material ids: index == id.
  var NAMES = ["empty", "sand", "water", "wall", "acid"];
  var MAT_EMPTY = 0, MAT_SAND = 1, MAT_WATER = 2, MAT_WALL = 3, MAT_ACID = 4;

  var nameToId = { empty: MAT_EMPTY, sand: MAT_SAND, water: MAT_WATER, wall: MAT_WALL, acid: MAT_ACID };

  // ---- Storage ----
  var grid = new Uint8Array(W * H);   // material id per cell
  var shade = new Uint8Array(W * H);  // per-cell brightness for texture
  var moved = new Uint8Array(W * H);  // "already moved this step" flag

  function idx(x, y) { return y * W + x; }

  // ---- Simulation: dissolve phase (acid eats sand/wall) ----
  function dissolve() {
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        var i = idx(x, y);
        if (grid[i] !== MAT_ACID) continue;

        // Acid evaporates slowly so it doesn't fill the world forever.
        if (Math.random() < EVAPORATE_PROB) { grid[i] = 0; shade[i] = 0; continue; }

        var targets = [];
        if (x > 0)            { var m = grid[i - 1];   if (m === MAT_SAND || m === MAT_WALL) targets.push(i - 1); }
        if (x < W - 1)        { m = grid[i + 1];       if (m === MAT_SAND || m === MAT_WALL) targets.push(i + 1); }
        if (y < H - 1)        { m = grid[i + W];       if (m === MAT_SAND || m === MAT_WALL) targets.push(i + W); }

        if (targets.length && Math.random() < DISSOLVE_PROB) {
          var t = targets[(Math.random() * targets.length) | 0];
          grid[t] = 0; shade[t] = 0; // erode the target (walls included)
        }
      }
    }
  }

  // ---- Simulation: movement phase, processed bottom-row-up so each
  //      particle moves at most one cell per step. ----
  function movePass() {
    moved.fill(0);
    for (var y = H - 1; y >= 0; y--) {
      for (var x = 0; x < W; x++) {
        var i = idx(x, y);
        if (moved[i]) continue;
        var m = grid[i];
        if (m === MAT_EMPTY || m === MAT_WALL) continue; // walls never move

        if (m === MAT_SAND) {
          // 1) fall straight down into empty
          if (y + 1 < H) {
            var below = i + W;
            var bm = grid[below];
            if (bm === MAT_EMPTY) { doMove(i, below); continue; }
            // 2) sink through liquid (swap: sand down, liquid up) — one cell only
            if (bm === MAT_WATER || bm === MAT_ACID) { swap(i, below); moved[below] = 1; continue; }
          }
          // 3) slide diagonally down-left / down-right (randomize first try)
          var dir = Math.random() < 0.5 ? -1 : 1;
          for (var k = 0; k < 2; k++) {
            var d = k === 0 ? dir : -dir;
            var nx = x + d, ny = y + 1;
            if (nx >= 0 && nx < W && ny < H) {
              var di = idx(nx, ny);
              var dm = grid[di];
              if (dm === MAT_EMPTY) { doMove(i, di); break; }
              if (dm === MAT_WATER || dm === MAT_ACID) { swap(i, di); moved[di] = 1; break; }
            }
          }
          // else: rests
        } else {
          // water / acid: fall into empty or diagonal-empty, then spread sideways
          var did = false;
          if (y + 1 < H && grid[i + W] === MAT_EMPTY) { doMove(i, i + W); did = true; }
          if (!did) {
            dir = Math.random() < 0.5 ? -1 : 1;
            for (var k2 = 0; k2 < 2; k2++) {
              d = k2 === 0 ? dir : -dir;
              var nx2 = x + d, ny2 = y + 1;
              if (nx2 >= 0 && nx2 < W && ny2 < H && grid[idx(nx2, ny2)] === MAT_EMPTY) { doMove(i, idx(nx2, ny2)); did = true; break; }
            }
          }
          if (!did) {
            // spread horizontally into empty cells (randomize direction)
            dir = Math.random() < 0.5 ? -1 : 1;
            for (var k3 = 0; k3 < 2; k3++) {
              d = k3 === 0 ? dir : -dir;
              var nx3 = x + d;
              if (nx3 >= 0 && nx3 < W && grid[idx(nx3, y)] === MAT_EMPTY) { doMove(i, idx(nx3, y)); break; }
            }
          }
        }
      }
    }
  }

  function doMove(src, dest) {
    grid[dest] = grid[src];
    shade[dest] = shade[src];
    grid[src] = 0;
    shade[src] = 0;
    moved[dest] = 1; // prevents a particle from moving twice in one step
  }

  function swap(a, b) {
    var tm = grid[a]; grid[a] = grid[b]; grid[b] = tm;
    var ts = shade[a]; shade[a] = shade[b]; shade[b] = ts;
  }

  // ---- Public API ----
  function tick(n) {
    for (var k = 0; k < n; k++) { dissolve(); movePass(); }
  }

  function get(x, y) {
    if (x < 0 || x >= W || y < 0 || y >= H) return "empty";
    return NAMES[grid[idx(x, y)]];
  }

  function set(x, y, material) {
    if (x < 0 || x >= W || y < 0 || y >= H) return;
    var id = nameToId[material];
    if (id === undefined) return; // ignore unknown materials
    var i = idx(x, y);
    grid[i] = id;
    shade[i] = (id === MAT_EMPTY) ? 0 : (190 + ((Math.random() * 60) | 0));
  }

  function clear() {
    grid.fill(0);
    shade.fill(0);
  }

  window.sim = {
    w: W,
    h: H,
    tick: tick,
    get: get,
    set: set,
    clear: clear
  };

  // ---- Tuning constants ----
  var DISSOLVE_PROB = 0.5;   // per-step chance an acid erodes a touching sand/wall
  var EVAPORATE_PROB = 0.01; // per-step chance an acid dissipates

  // ---- Rendering (fast ImageData path) ----
  var canvas = document.getElementById("sand");
  canvas.width = W;
  canvas.height = H;
  var ctx = canvas.getContext("2d");
  var img = ctx.createImageData(W, H);
  var data = img.data;

  function render() {
    for (var i = 0; i < W * H; i++) {
      var m = grid[i];
      var r, g, b;
      switch (m) {
        case MAT_SAND:   r = 226; g = 200; b = 138; break;
        case MAT_WATER:  r = 56;  g = 122; b = 218; break;
        case MAT_WALL:   r = 128; g = 132; b = 142; break;
        case MAT_ACID:   r = 130; g = 232; b = 96;  break;
        default:         r = 16;  g = 16;  b = 22;  break; // empty background
      }
      var f = (m === MAT_EMPTY) ? 1 : (0.72 + (shade[i] / 255) * 0.5);
      data[i * 4]     = r * f > 255 ? 255 : (r * f) | 0;
      data[i * 4 + 1] = g * f > 255 ? 255 : (g * f) | 0;
      data[i * 4 + 2] = b * f > 255 ? 255 : (b * f) | 0;
      data[i * 4 + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
  }

  // ---- Painting ----
  var currentMat = MAT_SAND;
  var brush = 3;

  function place(gx, gy) {
    if (gx < 0 || gx >= W || gy < 0 || gy >= H) return;
    var i = idx(gx, gy);
    grid[i] = currentMat;
    shade[i] = (currentMat === MAT_EMPTY) ? 0 : (190 + ((Math.random() * 60) | 0));
  }

  // Bresenham line so fast drags don't leave gaps.
  function paintLine(x0, y0, x1, y1) {
    var dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
    var sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
    var err = dx - dy, cx = x0, cy = y0;
    for (;;) {
      drawBrush(cx, cy);
      if (cx === x1 && cy === y1) break;
      var e2 = 2 * err;
      if (e2 > -dy) { err -= dy; cx += sx; }
      if (e2 < dx)  { err += dx; cy += sy; }
    }
  }

  function drawBrush(cx, cy) {
